package com.bank.stats.service;

import com.bank.stats.dto.StatsReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class ChannelStatsService {

    private final List<String> transactions = List.of(
        "NEFT", "UPI", "NEFT", "RTGS", "UPI", "NEFT", "IMPS", "UPI",
        "NEFT", "UPI", "RTGS", "IMPS", "UPI", "NEFT", "UPI", "NEFT",
        "RTGS", "IMPS", "UPI", "NEFT"
    );

    public StatsReport generateStats() {

        // ═══ FREQUENCY MAP (sorted keys) ═══
        Map<String, Long> freq = transactions.stream()
            .collect(Collectors.groupingBy(Function.identity(),
                TreeMap::new, Collectors.counting()));
        log.info("Frequency: {}", freq);

        // ═══ RANKED BY USAGE (descending) ═══
        List<String> ranked = freq.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .map(e -> e.getKey() + ": " + e.getValue() + " (" +
                String.format("%.0f%%", (double) e.getValue() / transactions.size() * 100) + ")")
            .toList();

        // ═══ MOST and LEAST used ═══
        String mostUsed = freq.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(e -> e.getKey() + " (" + e.getValue() + " txns)")
            .orElse("N/A");

        String leastUsed = freq.entrySet().stream()
            .min(Map.Entry.comparingByValue())
            .map(e -> e.getKey() + " (" + e.getValue() + " txns)")
            .orElse("N/A");

        return new StatsReport(transactions.size(), freq, ranked, mostUsed, leastUsed);
    }
}
