package com.bank.stats.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class FrequencyCountTest {

    @Test
    void basicFrequencyCount() {
        Map<String, Long> freq = List.of("A", "B", "A", "C", "B", "A").stream()
            .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
        assertThat(freq).containsEntry("A", 3L).containsEntry("B", 2L).containsEntry("C", 1L);
    }

    @Test
    void sortedKeysWithTreeMap() {
        Map<String, Long> freq = List.of("UPI", "NEFT", "UPI", "IMPS").stream()
            .collect(Collectors.groupingBy(Function.identity(), TreeMap::new, Collectors.counting()));
        assertThat(new ArrayList<>(freq.keySet())).containsExactly("IMPS", "NEFT", "UPI");
    }

    @Test
    void rankedByFrequency() {
        List<String> ranked = List.of("A", "B", "A", "C", "B", "A").stream()
            .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()))
            .entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .map(Map.Entry::getKey)
            .toList();
        assertThat(ranked).containsExactly("A", "B", "C");
    }

    @Test
    void caseInsensitive() {
        Map<String, Long> freq = List.of("Neft", "NEFT", "neft", "UPI").stream()
            .map(String::toUpperCase)
            .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
        assertThat(freq).containsEntry("NEFT", 3L).containsEntry("UPI", 1L);
    }

    @Test
    void emptyList() {
        Map<String, Long> freq = List.<String>of().stream()
            .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
        assertThat(freq).isEmpty();
    }
}
